(9, 1, 573, 1, 4, 'qwen2.5:0.5b', '{\"mode\":\"simple\",\"grounded_question_id\":1}', 'A student is a learner who attends school.', NULL, '2026-06-19 12:17:19'),
(10, 1, 573, 1, 4, 'qwen2.5:0.5b', '{\"mode\":\"simple\",\"grounded_question_id\":1}', 'A student means a young learner at school.', NULL, '2026-06-19 12:17:32'),
