INSERT INTO `generated_question_batches` (`id`, `school_id`, `teacher_id`, `grade_id`, `subject_id`, `topic_id`, `subtopic_id`, `number_requested`, `difficulty`, `question_type`, `status`, `ai_model_used`, `generation_prompt`, `raw_response_json`, `error_message`, `created_at`, `updated_at`) VALUES
(10, 1, 32, 35, 31, 136, NULL, 5, 'easy', 'multiple_choice', 'pending_review', 'gemini-2.5-flash', '{\"curriculum\":\"Cambridge Primary Curriculum\",\"gradeName\":\"Year 1\",\"subjectName\":\"Agriculture\",\"topicName\":\"Agricultural Economics and Far Business\",\"subtopicName\":\"\",\"difficulty\":\"easy\",\"questionType\":\"multiple_choice\",\"numberOfQuestions\":5,\"examTrack\":\"\",\"languageLevel\":\"\",\"includeExplanations\":true,\"schoolId\":1,\"userId\":32,\"approvedSyllabusContext\":{\"approved_topics\":[{\"id\":136,\"topic_name\":\"Agricultural Economics and Far Business\",\"description\":null,\"term\":\"Term 3\",\"parent_topic_name\":null}],\"approved_objectives\":[],\"approved_chunks\":[]}}', '{\"raw\":\"{\\n  \\\"questions\\\": [\\n    {\\n      \\\"question_text\\\": \\\"What do farmers grow in their fields to sell?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Toys\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Books\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"Vegetables\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"Cars\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"C\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"C\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Farmers grow crops like vegetables, fruits, and grains in their fields. They sell these to people so they can eat them.\\\",\\n      \\\"common_mistake\\\": \\\"Some children might think farmers sell things they see in shops, not realizing they produce the food first.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"recall\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Why do farmers sell the food they grow or the milk from their cows?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"To play games\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"To get money\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"To make friends\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"To sleep\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"B\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Farmers sell their produce to get money. This money helps them buy things they need for the farm and for their families, like seeds, tools, and clothes.\\\",\\n      \\\"common_mistake\\\": \\\"Children might not connect selling with earning money for necessities.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"recall\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"What might a farmer need to buy for their farm?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Candy\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"New shoes\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"Seeds for planting\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"A television\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"C\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"C\\\"\\n      ],\\n      \\\"explanation\\\": \\\"To grow new crops, farmers need to buy seeds. They also buy other things like animal feed, tools, and fuel for their tractors.\\\",\\n      \\\"common_mistake\\\": \\\"Students might choose personal items rather than farm-related necessities.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"recall\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Who often helps a farmer with their work on the farm?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"The postman\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Their family\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"The doctor\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"The teacher\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"B\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Farms are often family businesses, and many family members help with different jobs like planting, harvesting, or taking care of animals.\\\",\\n      \\\"common_mistake\\\": \\\"Children might think only one person works on a farm, or choose other community helpers.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"recall\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"What is a \'farm business\' mostly about?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Playing all day\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Making decisions about what to grow and sell\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"Watching movies\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"Eating snacks\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"B\\\"\\n      ],\\n      \\\"explanation\\\": \\\"A farm business is about making choices, like what crops to plant, which animals to raise, and how to sell them to earn money. It\'s like running a small shop that sells food.\\\",\\n      \\\"common_mistake\\\": \\\"Students might confuse \'business\' with leisure activities.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"comprehension\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    }\\n  ]\\n}\",\"data\":{\"questions\":[{\"question_text\":\"What do farmers grow in their fields to sell?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"Toys\"},{\"label\":\"B\",\"text\":\"Books\"},{\"label\":\"C\",\"text\":\"Vegetables\"},{\"label\":\"D\",\"text\":\"Cars\"}],\"correct_answer\":\"C\",\"accepted_answers\":[\"C\"],\"explanation\":\"Farmers grow crops like vegetables, fruits, and grains in their fields. They sell these to people so they can eat them.\",\"common_mistake\":\"Some children might think farmers sell things they see in shops, not realizing they produce the food first.\",\"difficulty\":\"easy\",\"skill_type\":\"recall\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"Why do farmers sell the food they grow or the milk from their cows?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"To play games\"},{\"label\":\"B\",\"text\":\"To get money\"},{\"label\":\"C\",\"text\":\"To make friends\"},{\"label\":\"D\",\"text\":\"To sleep\"}],\"correct_answer\":\"B\",\"accepted_answers\":[\"B\"],\"explanation\":\"Farmers sell their produce to get money. This money helps them buy things they need for the farm and for their families, like seeds, tools, and clothes.\",\"common_mistake\":\"Children might not connect selling with earning money for necessities.\",\"difficulty\":\"easy\",\"skill_type\":\"recall\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"What might a farmer need to buy for their farm?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"Candy\"},{\"label\":\"B\",\"text\":\"New shoes\"},{\"label\":\"C\",\"text\":\"Seeds for planting\"},{\"label\":\"D\",\"text\":\"A television\"}],\"correct_answer\":\"C\",\"accepted_answers\":[\"C\"],\"explanation\":\"To grow new crops, farmers need to buy seeds. They also buy other things like animal feed, tools, and fuel for their tractors.\",\"common_mistake\":\"Students might choose personal items rather than farm-related necessities.\",\"difficulty\":\"easy\",\"skill_type\":\"recall\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"Who often helps a farmer with their work on the farm?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"The postman\"},{\"label\":\"B\",\"text\":\"Their family\"},{\"label\":\"C\",\"text\":\"The doctor\"},{\"label\":\"D\",\"text\":\"The teacher\"}],\"correct_answer\":\"B\",\"accepted_answers\":[\"B\"],\"explanation\":\"Farms are often family businesses, and many family members help with different jobs like planting, harvesting, or taking care of animals.\",\"common_mistake\":\"Children might think only one person works on a farm, or choose other community helpers.\",\"difficulty\":\"easy\",\"skill_type\":\"recall\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"What is a \'farm business\' mostly about?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"Playing all day\"},{\"label\":\"B\",\"text\":\"Making decisions about what to grow and sell\"},{\"label\":\"C\",\"text\":\"Watching movies\"},{\"label\":\"D\",\"text\":\"Eating snacks\"}],\"correct_answer\":\"B\",\"accepted_answers\":[\"B\"],\"explanation\":\"A farm business is about making choices, like what crops to plant, which animals to raise, and how to sell them to earn money. It\'s like running a small shop that sells food.\",\"common_mistake\":\"Students might confuse \'business\' with leisure activities.\",\"difficulty\":\"easy\",\"skill_type\":\"comprehension\",\"marks\":1,\"confidence\":0.9}]}}', NULL, '2026-06-20 16:16:25', '2026-06-20 16:16:40'),
(11, 1, 32, 35, 31, 137, NULL, 5, 'easy', 'short_answer', 'pending_review', 'gemini-2.5-flash', '{\"curriculum\":\"Cambridge Primary Curriculum\",\"gradeName\":\"Year 1\",\"subjectName\":\"Agriculture\",\"topicName\":\"Marketing Factors\",\"subtopicName\":\"\",\"difficulty\":\"easy\",\"questionType\":\"short_answer\",\"numberOfQuestions\":5,\"examTrack\":\"\",\"languageLevel\":\"\",\"includeExplanations\":true,\"schoolId\":1,\"userId\":32,\"approvedSyllabusContext\":{\"approved_topics\":[{\"id\":137,\"topic_name\":\"Marketing Factors\",\"description\":null,\"term\":\"Term 3\",\"parent_topic_name\":\"Agricultural Economics and Far Business\"}],\"approved_objectives\":[{\"topic_id\":137,\"objective_text\":\"Define main factors of agricultural production\",\"skill_type\":\"define\",\"exam_relevance\":null},{\"topic_id\":137,\"objective_text\":\"List main factors of agricultural production\",\"skill_type\":\"list\",\"exam_relevance\":null},{\"topic_id\":137,\"objective_text\":\"Explain main factors of agricultural production\",\"skill_type\":\"explain\",\"exam_relevance\":null},{\"topic_id\":137,\"objective_text\":\"Identify main factors of agricultural production\",\"skill_type\":\"identify\",\"exam_relevance\":null}],\"approved_chunks\":[]}}', '{\"raw\":\"{\\n  \\\"questions\\\": [\\n    {\\n      \\\"question_text\\\": \\\"What is the ground called where a farmer grows crops?\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Land\\\",\\n      \\\"accepted_answers_json\\\": [\\\"Land\\\", \\\"Field\\\", \\\"Soil\\\"],\\n      \\\"explanation\\\": \\\"Land is a main factor of agricultural production because it\'s the essential space where crops are grown and animals can live. Without land, farming cannot happen.\\\",\\n      \\\"common_mistake\\\": \\\"Students might name a specific crop (e.g., \'corn\') or an animal (e.g., \'cow\') instead of the land itself, confusing the product with the factor of production.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"identify\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Name one person who works on a farm to help grow food.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Farmer\\\",\\n      \\\"accepted_answers_json\\\": [\\\"Farmer\\\", \\\"Helper\\\", \\\"Worker\\\"],\\n      \\\"explanation\\\": \\\"Labor, which refers to the people working, is a main factor because farmers and their helpers do all the physical and mental work to plant, care for, and harvest crops, as well as look after animals.\\\",\\n      \\\"common_mistake\\\": \\\"Students might name an animal (e.g., \'chicken\') or a machine (e.g., \'tractor\') instead of a person involved in the labor.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"list\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"What do farmers use to buy things like seeds, tools, or tractors?\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Money\\\",\\n      \\\"accepted_answers_json\\\": [\\\"Money\\\", \\\"Capital\\\", \\\"Funds\\\"],\\n      \\\"explanation\\\": \\\"Capital refers to the money, tools, machines, and buildings farmers use to run their farm. It\'s a main factor because these resources are needed to acquire supplies and equipment for production.\\\",\\n      \\\"common_mistake\\\": \\\"Students might name a specific tool (e.g., \'tractor\') instead of the general concept of money or capital that allows them to acquire such tools.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"identify\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Why is it important for a farmer to have a good plan for their farm?\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"To grow good food\\\",\\n      \\\"accepted_answers_json\\\": [\\\"To grow good food\\\", \\\"To make the farm work well\\\", \\\"To know what to do\\\", \\\"To be successful\\\"],\\n      \\\"explanation\\\": \\\"Management (or entrepreneurship) is about the farmer\'s skills in planning, organizing, and making decisions for the farm. It\'s a main factor because good planning helps the farm be efficient and successful in producing food.\\\",\\n      \\\"common_mistake\\\": \\\"Students might give a very general answer like \'to be happy\' without linking it to the practical success or output of the farm.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"explain\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.8\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Name one of the main things a farmer needs to grow crops, besides people.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Land\\\",\\n      \\\"accepted_answers_json\\\": [\\\"Land\\\", \\\"Money\\\", \\\"Tools\\\", \\\"Tractor\\\", \\\"Seeds\\\"],\\n      \\\"explanation\\\": \\\"Besides labor (people), farmers need other main factors like land to plant on and capital (such as money, tools, or seeds) to help them grow crops. These are fundamental for agricultural production.\\\",\\n      \\\"common_mistake\\\": \\\"Students might name a person (which was excluded by the question) or an animal, rather than focusing on the other core factors of production.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"list\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    }\\n  ]\\n}\",\"data\":{\"questions\":[{\"question_text\":\"What is the ground called where a farmer grows crops?\",\"question_type\":\"short_answer\",\"options\":[],\"correct_answer\":\"Land\",\"accepted_answers\":[\"Land\",\"Field\",\"Soil\"],\"explanation\":\"Land is a main factor of agricultural production because it\'s the essential space where crops are grown and animals can live. Without land, farming cannot happen.\",\"common_mistake\":\"Students might name a specific crop (e.g., \'corn\') or an animal (e.g., \'cow\') instead of the land itself, confusing the product with the factor of production.\",\"difficulty\":\"easy\",\"skill_type\":\"identify\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"Name one person who works on a farm to help grow food.\",\"question_type\":\"short_answer\",\"options\":[],\"correct_answer\":\"Farmer\",\"accepted_answers\":[\"Farmer\",\"Helper\",\"Worker\"],\"explanation\":\"Labor, which refers to the people working, is a main factor because farmers and their helpers do all the physical and mental work to plant, care for, and harvest crops, as well as look after animals.\",\"common_mistake\":\"Students might name an animal (e.g., \'chicken\') or a machine (e.g., \'tractor\') instead of a person involved in the labor.\",\"difficulty\":\"easy\",\"skill_type\":\"list\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"What do farmers use to buy things like seeds, tools, or tractors?\",\"question_type\":\"short_answer\",\"options\":[],\"correct_answer\":\"Money\",\"accepted_answers\":[\"Money\",\"Capital\",\"Funds\"],\"explanation\":\"Capital refers to the money, tools, machines, and buildings farmers use to run their farm. It\'s a main factor because these resources are needed to acquire supplies and equipment for production.\",\"common_mistake\":\"Students might name a specific tool (e.g., \'tractor\') instead of the general concept of money or capital that allows them to acquire such tools.\",\"difficulty\":\"easy\",\"skill_type\":\"identify\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"Why is it important for a farmer to have a good plan for their farm?\",\"question_type\":\"short_answer\",\"options\":[],\"correct_answer\":\"To grow good food\",\"accepted_answers\":[\"To grow good food\",\"To make the farm work well\",\"To know what to do\",\"To be successful\"],\"explanation\":\"Management (or entrepreneurship) is about the farmer\'s skills in planning, organizing, and making decisions for the farm. It\'s a main factor because good planning helps the farm be efficient and successful in producing food.\",\"common_mistake\":\"Students might give a very general answer like \'to be happy\' without linking it to the practical success or output of the farm.\",\"difficulty\":\"easy\",\"skill_type\":\"explain\",\"marks\":1,\"confidence\":0.8},{\"question_text\":\"Name one of the main things a farmer needs to grow crops, besides people.\",\"question_type\":\"short_answer\",\"options\":[],\"correct_answer\":\"Land\",\"accepted_answers\":[\"Land\",\"Money\",\"Tools\",\"Tractor\",\"Seeds\"],\"explanation\":\"Besides labor (people), farmers need other main factors like land to plant on and capital (such as money, tools, or seeds) to help them grow crops. These are fundamental for agricultural production.\",\"common_mistake\":\"Students might name a person (which was excluded by the question) or an animal, rather than focusing on the other core factors of production.\",\"difficulty\":\"easy\",\"skill_type\":\"list\",\"marks\":1,\"confidence\":0.9}]}}', NULL, '2026-06-20 17:09:39', '2026-06-20 17:09:55'),
(12, 1, 32, 37, 35, 215, NULL, 5, 'medium', 'structured', 'pending_review', 'gemini-2.5-flash', '{\"curriculum\":\"Cambridge Primary Curriculum\",\"gradeName\":\"Year 3\",\"subjectName\":\"Computer Studies\",\"topicName\":\"Year 3 Computer Studies Syllabus\",\"subtopicName\":\"\",\"difficulty\":\"medium\",\"questionType\":\"structured\",\"numberOfQuestions\":5,\"examTrack\":\"\",\"languageLevel\":\"\",\"includeExplanations\":true,\"schoolId\":1,\"userId\":32,\"approvedSyllabusContext\":{\"approved_topics\":[{\"id\":217,\"topic_name\":\"Parts of a Computer\",\"description\":\"Monitor, keyboard, mouse, system unit and speakers.\",\"term\":null,\"parent_topic_id\":216,\"parent_topic_name\":\"Computer Basics\"},{\"id\":218,\"topic_name\":\"Using Input Devices\",\"description\":\"Mouse clicks, keyboard keys and simple typing practice.\",\"term\":null,\"parent_topic_id\":216,\"parent_topic_name\":\"Computer Basics\"},{\"id\":221,\"topic_name\":\"Creating Simple Documents\",\"description\":\"Typing, editing and adding a title to simple class work.\",\"term\":null,\"parent_topic_id\":219,\"parent_topic_name\":\"Digital Safety and Creation\"},{\"id\":220,\"topic_name\":\"Safe Computer Use\",\"description\":\"Posture, sharing devices, passwords and asking an adult for help.\",\"term\":null,\"parent_topic_id\":219,\"parent_topic_name\":\"Digital Safety and Creation\"},{\"id\":215,\"topic_name\":\"Year 3 Computer Studies Syllabus\",\"description\":\"Standing Cambridge Primary Year 3 Computer Studies syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.\",\"term\":null,\"parent_topic_id\":null,\"parent_topic_name\":null},{\"id\":216,\"topic_name\":\"Computer Basics\",\"description\":\"Parts of a computer and simple safe use routines.\",\"term\":null,\"parent_topic_id\":215,\"parent_topic_name\":\"Year 3 Computer Studies Syllabus\"},{\"id\":219,\"topic_name\":\"Digital Safety and Creation\",\"description\":\"Responsible use of devices and creating simple digital work.\",\"term\":null,\"parent_topic_id\":215,\"parent_topic_name\":\"Year 3 Computer Studies Syllabus\"}],\"approved_success_criteria\":[{\"topic_id\":217,\"action_tag\":\"identify\",\"text\":\"Identify main parts of a desktop computer\",\"exam_relevance\":null},{\"topic_id\":217,\"action_tag\":\"label\",\"text\":\"Label main parts of a desktop computer\",\"exam_relevance\":null},{\"topic_id\":217,\"action_tag\":\"explain\",\"text\":\"Explain computer parts to their basic functions\",\"exam_relevance\":null},{\"topic_id\":217,\"action_tag\":\"match\",\"text\":\"Match computer parts to their basic functions\",\"exam_relevance\":null},{\"topic_id\":218,\"action_tag\":\"describe\",\"text\":\"Describe safe use of a mouse and keyboard\",\"exam_relevance\":null},{\"topic_id\":218,\"action_tag\":\"demonstrate\",\"text\":\"Demonstrate safe use of a mouse and keyboard\",\"exam_relevance\":null},{\"topic_id\":218,\"action_tag\":\"list\",\"text\":\"List steps for opening and closing a simple program\",\"exam_relevance\":null},{\"topic_id\":218,\"action_tag\":\"apply\",\"text\":\"Apply steps for opening and closing a simple program\",\"exam_relevance\":null},{\"topic_id\":220,\"action_tag\":\"list\",\"text\":\"List rules for safe and responsible computer use\",\"exam_relevance\":null},{\"topic_id\":220,\"action_tag\":\"explain\",\"text\":\"Explain rules for safe and responsible computer use\",\"exam_relevance\":null},{\"topic_id\":220,\"action_tag\":\"identify\",\"text\":\"Identify private information that should not be shared\",\"exam_relevance\":null},{\"topic_id\":220,\"action_tag\":\"state\",\"text\":\"State private information that should not be shared\",\"exam_relevance\":null},{\"topic_id\":221,\"action_tag\":\"create\",\"text\":\"Create a simple document with a title and short sentences\",\"exam_relevance\":null},{\"topic_id\":221,\"action_tag\":\"format\",\"text\":\"Format a simple document with a title and short sentences\",\"exam_relevance\":null},{\"topic_id\":221,\"action_tag\":\"save\",\"text\":\"Save why files should be saved with clear names\",\"exam_relevance\":null},{\"topic_id\":221,\"action_tag\":\"explain\",\"text\":\"Explain why files should be saved with clear names\",\"exam_relevance\":null}],\"approved_chunks\":[]},\"assessmentQuestionHistory\":[]}', '{\"raw\":\"{\\n  \\\"questions\\\": [\\n    {\\n      \\\"question_text\\\": \\\"Name two main parts of a desktop computer and explain one basic function for each part you named.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Award 1 mark for each correctly named computer part (e.g., Monitor, Keyboard, Mouse, System Unit, Speakers). Award 1 mark for a correct basic function for each named part. For example: Monitor - shows what is happening on the computer screen; Keyboard - used to type letters and numbers; Mouse - used to click on things and move the pointer; System Unit - the \'brain\' of the computer where all the processing happens; Speakers - play sounds from the computer.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Monitor: displays images/text\\\",\\n        \\\"Keyboard: types letters/numbers\\\",\\n        \\\"Mouse: clicks/moves pointer\\\",\\n        \\\"System Unit: processes information\\\",\\n        \\\"Speakers: plays sound\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Understanding the main parts of a computer and their basic functions is fundamental to using a computer effectively. Each part plays a specific role in how you interact with the computer and how it processes information.\\\",\\n      \\\"common_mistake\\\": \\\"Students might name a part but struggle to explain its function clearly, or confuse the functions of similar parts (e.g., monitor and speakers both output information, but one is visual and the other is audio).\\\",\\n      \\\"difficulty\\\": \\\"medium\\\",\\n      \\\"skill_type\\\": \\\"explain\\\",\\n      \\\"marks\\\": 4,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Describe two important rules for using a computer mouse safely to prevent discomfort or injury to your hand and wrist.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Award 2 marks for each clear and correct rule for safe mouse use. Examples include: 1. Keep your wrist straight and relaxed, not bent. 2. Use a light grip on the mouse, don\'t squeeze it too hard. 3. Take short breaks often to rest your hand. 4. Use your whole arm to move the mouse, not just your wrist. 5. Ensure the mouse is close to your body.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Keep wrist straight and relaxed\\\",\\n        \\\"Use a light grip on the mouse\\\",\\n        \\\"Take regular breaks\\\",\\n        \\\"Move mouse with arm, not just wrist\\\",\\n        \\\"Keep mouse close to body\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Using input devices like the mouse and keyboard correctly is important for your health. Maintaining good posture and safe habits helps prevent strain and discomfort, especially when using the computer for extended periods.\\\",\\n      \\\"common_mistake\\\": \\\"Students might focus on general computer safety (like not eating near the computer) rather than specific physical safety related to mouse use. They might also give vague answers like \'be careful\'.\\\",\\n      \\\"difficulty\\\": \\\"medium\\\",\\n      \\\"skill_type\\\": \\\"describe\\\",\\n      \\\"marks\\\": 4,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Explain why it is important to ask an adult for help if you see something on the computer that makes you feel uncomfortable. Give one example of private information you should never share online.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Award 2 marks for explaining why to ask an adult: Adults can help understand what you saw, protect you from harmful content, or report inappropriate content. Award 2 marks for one correct example of private information: full name, home address, phone number, school name, passwords, photos of yourself or family without permission.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Adults can help understand/protect/report\\\",\\n        \\\"Full name\\\",\\n        \\\"Home address\\\",\\n        \\\"Phone number\\\",\\n        \\\"School name\\\",\\n        \\\"Passwords\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Digital safety is crucial. If something makes you uncomfortable online, an adult can provide guidance and ensure your safety. Sharing private information can put you at risk, so it\'s vital to know what to keep secret.\\\",\\n      \\\"common_mistake\\\": \\\"Students might struggle to articulate *why* asking an adult is important beyond \'they will help\'. For private information, they might list things that aren\'t strictly private (e.g., favorite color).\\\",\\n      \\\"difficulty\\\": \\\"medium\\\",\\n      \\\"skill_type\\\": \\\"explain\\\",\\n      \\\"marks\\\": 4,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Imagine you have created a drawing of a cat and a story about a dog on the computer. Explain why it is important to save these files with clear and different names.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Award 1 mark for each valid reason, up to 3 marks. Reasons include: 1. To easily find the files later. 2. To know what is inside each file without opening it. 3. To prevent accidentally overwriting one file with another if they have the same name. 4. To keep your computer files organised.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Easily find files later\\\",\\n        \\\"Know content without opening\\\",\\n        \\\"Prevent overwriting files\\\",\\n        \\\"Keep files organised\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Saving files with clear and distinct names is a good practice for digital organisation. It helps you manage your work, find what you need quickly, and avoid losing important documents.\\\",\\n      \\\"common_mistake\\\": \\\"Students might only give one reason or state \'it\'s good to save\' without explaining *why* clear and different names are important.\\\",\\n      \\\"difficulty\\\": \\\"medium\\\",\\n      \\\"skill_type\\\": \\\"explain\\\",\\n      \\\"marks\\\": 3,\\n      \\\"confidence\\\": 0.85\\n    },\\n    {\\n      \\\"question_text\\\": \\\"List the basic steps you would take to open a simple drawing program on the computer and then close it when you are finished.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Award 1 mark for each correct step, up to 4 marks. \\\\nTo open: 1. Click on the Start button (or equivalent). 2. Find the drawing program icon/name. 3. Click on the icon/name to open it. \\\\nTo close: 1. Click on the \'X\' button in the top right corner of the program window. 2. If prompted, choose to save your work or not.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Click Start button\\\",\\n        \\\"Find program icon/name\\\",\\n        \\\"Click icon/name to open\\\",\\n        \\\"Click \'X\' button to close\\\",\\n        \\\"Choose to save/not save if prompted\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Knowing how to open and close programs is a fundamental skill for using a computer. These steps are common across many applications and operating systems.\\\",\\n      \\\"common_mistake\\\": \\\"Students might miss a step, such as clicking the \'X\' to close, or might not mention the \'Start\' button for opening. They might also confuse opening/closing with turning the computer on/off.\\\",\\n      \\\"difficulty\\\": \\\"medium\\\",\\n      \\\"skill_type\\\": \\\"list\\\",\\n      \\\"marks\\\": 4,\\n      \\\"confidence\\\": 0.9\\n    }\\n  ]\\n}\",\"data\":{\"questions\":[{\"question_text\":\"Name two main parts of a desktop computer and explain one basic function for each part you named.\",\"question_type\":\"structured\",\"options\":[],\"correct_answer\":\"Award 1 mark for each correctly named computer part (e.g., Monitor, Keyboard, Mouse, System Unit, Speakers). Award 1 mark for a correct basic function for each named part. For example: Monitor - shows what is happening on the computer screen; Keyboard - used to type letters and numbers; Mouse - used to click on things and move the pointer; System Unit - the \'brain\' of the computer where all the processing happens; Speakers - play sounds from the computer.\",\"accepted_answers\":[\"Monitor: displays images/text\",\"Keyboard: types letters/numbers\",\"Mouse: clicks/moves pointer\",\"System Unit: processes information\",\"Speakers: plays sound\"],\"explanation\":\"Understanding the main parts of a computer and their basic functions is fundamental to using a computer effectively. Each part plays a specific role in how you interact with the computer and how it processes information.\",\"common_mistake\":\"Students might name a part but struggle to explain its function clearly, or confuse the functions of similar parts (e.g., monitor and speakers both output information, but one is visual and the other is audio).\",\"difficulty\":\"medium\",\"skill_type\":\"explain\",\"marks\":4,\"confidence\":0.9},{\"question_text\":\"Describe two important rules for using a computer mouse safely to prevent discomfort or injury to your hand and wrist.\",\"question_type\":\"structured\",\"options\":[],\"correct_answer\":\"Award 2 marks for each clear and correct rule for safe mouse use. Examples include: 1. Keep your wrist straight and relaxed, not bent. 2. Use a light grip on the mouse, don\'t squeeze it too hard. 3. Take short breaks often to rest your hand. 4. Use your whole arm to move the mouse, not just your wrist. 5. Ensure the mouse is close to your body.\",\"accepted_answers\":[\"Keep wrist straight and relaxed\",\"Use a light grip on the mouse\",\"Take regular breaks\",\"Move mouse with arm, not just wrist\",\"Keep mouse close to body\"],\"explanation\":\"Using input devices like the mouse and keyboard correctly is important for your health. Maintaining good posture and safe habits helps prevent strain and discomfort, especially when using the computer for extended periods.\",\"common_mistake\":\"Students might focus on general computer safety (like not eating near the computer) rather than specific physical safety related to mouse use. They might also give vague answers like \'be careful\'.\",\"difficulty\":\"medium\",\"skill_type\":\"describe\",\"marks\":4,\"confidence\":0.9},{\"question_text\":\"Explain why it is important to ask an adult for help if you see something on the computer that makes you feel uncomfortable. Give one example of private information you should never share online.\",\"question_type\":\"structured\",\"options\":[],\"correct_answer\":\"Award 2 marks for explaining why to ask an adult: Adults can help understand what you saw, protect you from harmful content, or report inappropriate content. Award 2 marks for one correct example of private information: full name, home address, phone number, school name, passwords, photos of yourself or family without permission.\",\"accepted_answers\":[\"Adults can help understand/protect/report\",\"Full name\",\"Home address\",\"Phone number\",\"School name\",\"Passwords\"],\"explanation\":\"Digital safety is crucial. If something makes you uncomfortable online, an adult can provide guidance and ensure your safety. Sharing private information can put you at risk, so it\'s vital to know what to keep secret.\",\"common_mistake\":\"Students might struggle to articulate *why* asking an adult is important beyond \'they will help\'. For private information, they might list things that aren\'t strictly private (e.g., favorite color).\",\"difficulty\":\"medium\",\"skill_type\":\"explain\",\"marks\":4,\"confidence\":0.9},{\"question_text\":\"Imagine you have created a drawing of a cat and a story about a dog on the computer. Explain why it is important to save these files with clear and different names.\",\"question_type\":\"structured\",\"options\":[],\"correct_answer\":\"Award 1 mark for each valid reason, up to 3 marks. Reasons include: 1. To easily find the files later. 2. To know what is inside each file without opening it. 3. To prevent accidentally overwriting one file with another if they have the same name. 4. To keep your computer files organised.\",\"accepted_answers\":[\"Easily find files later\",\"Know content without opening\",\"Prevent overwriting files\",\"Keep files organised\"],\"explanation\":\"Saving files with clear and distinct names is a good practice for digital organisation. It helps you manage your work, find what you need quickly, and avoid losing important documents.\",\"common_mistake\":\"Students might only give one reason or state \'it\'s good to save\' without explaining *why* clear and different names are important.\",\"difficulty\":\"medium\",\"skill_type\":\"explain\",\"marks\":3,\"confidence\":0.85},{\"question_text\":\"List the basic steps you would take to open a simple drawing program on the computer and then close it when you are finished.\",\"question_type\":\"structured\",\"options\":[],\"correct_answer\":\"Award 1 mark for each correct step, up to 4 marks. \\nTo open: 1. Click on the Start button (or equivalent). 2. Find the drawing program icon/name. 3. Click on the icon/name to open it. \\nTo close: 1. Click on the \'X\' button in the top right corner of the program window. 2. If prompted, choose to save your work or not.\",\"accepted_answers\":[\"Click Start button\",\"Find program icon/name\",\"Click icon/name to open\",\"Click \'X\' button to close\",\"Choose to save/not save if prompted\"],\"explanation\":\"Knowing how to open and close programs is a fundamental skill for using a computer. These steps are common across many applications and operating systems.\",\"common_mistake\":\"Students might miss a step, such as clicking the \'X\' to close, or might not mention the \'Start\' button for opening. They might also confuse opening/closing with turning the computer on/off.\",\"difficulty\":\"medium\",\"skill_type\":\"list\",\"marks\":4,\"confidence\":0.9}]}}', NULL, '2026-06-21 07:39:46', '2026-06-21 07:50:54');
INSERT INTO `generated_question_batches` (`id`, `school_id`, `teacher_id`, `grade_id`, `subject_id`, `topic_id`, `subtopic_id`, `number_requested`, `difficulty`, `question_type`, `status`, `ai_model_used`, `generation_prompt`, `raw_response_json`, `error_message`, `created_at`, `updated_at`) VALUES
(13, 1, 32, 37, 27, 201, NULL, 20, 'easy', 'structured', 'pending_review', 'gemini-2.5-flash', '{\"curriculum\":\"Cambridge Primary Curriculum\",\"gradeName\":\"Year 3\",\"subjectName\":\"Geography\",\"topicName\":\"Year 3 Geography Syllabus\",\"subtopicName\":\"\",\"difficulty\":\"easy\",\"questionType\":\"mixed\",\"numberOfQuestions\":20,\"examTrack\":\"\",\"languageLevel\":\"\",\"includeExplanations\":true,\"schoolId\":1,\"userId\":32,\"approvedSyllabusContext\":{\"approved_topics\":[{\"id\":204,\"topic_name\":\"Caring for Places\",\"description\":\"Keeping spaces clean and protecting natural resources.\",\"term\":null,\"parent_topic_id\":202,\"parent_topic_name\":\"Local Environment\"},{\"id\":203,\"topic_name\":\"Natural and Human Features\",\"description\":\"Rivers, hills, roads, schools, bridges and homes.\",\"term\":null,\"parent_topic_id\":202,\"parent_topic_name\":\"Local Environment\"},{\"id\":206,\"topic_name\":\"Simple Maps\",\"description\":\"Classroom maps, symbols and position words.\",\"term\":null,\"parent_topic_id\":205,\"parent_topic_name\":\"Maps, Direction and Weather\"},{\"id\":207,\"topic_name\":\"Weather Observation\",\"description\":\"Sunny, cloudy, rainy and windy weather with basic recording.\",\"term\":null,\"parent_topic_id\":205,\"parent_topic_name\":\"Maps, Direction and Weather\"},{\"id\":201,\"topic_name\":\"Year 3 Geography Syllabus\",\"description\":\"Standing Cambridge Primary Year 3 Geography syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.\",\"term\":null,\"parent_topic_id\":null,\"parent_topic_name\":null},{\"id\":202,\"topic_name\":\"Local Environment\",\"description\":\"Physical and human features learners can observe around them.\",\"term\":null,\"parent_topic_id\":201,\"parent_topic_name\":\"Year 3 Geography Syllabus\"},{\"id\":205,\"topic_name\":\"Maps, Direction and Weather\",\"description\":\"Simple map symbols, directions and daily weather observations.\",\"term\":null,\"parent_topic_id\":201,\"parent_topic_name\":\"Year 3 Geography Syllabus\"}],\"approved_success_criteria\":[{\"topic_id\":203,\"action_tag\":\"define\",\"text\":\"Define natural features and human-made features\",\"exam_relevance\":null},{\"topic_id\":203,\"action_tag\":\"classify\",\"text\":\"Classify natural features and human-made features\",\"exam_relevance\":null},{\"topic_id\":203,\"action_tag\":\"identify\",\"text\":\"Identify features found in the local environment\",\"exam_relevance\":null},{\"topic_id\":203,\"action_tag\":\"describe\",\"text\":\"Describe features found in the local environment\",\"exam_relevance\":null},{\"topic_id\":204,\"action_tag\":\"list\",\"text\":\"List ways to care for the school and community environment\",\"exam_relevance\":null},{\"topic_id\":204,\"action_tag\":\"explain\",\"text\":\"Explain ways to care for the school and community environment\",\"exam_relevance\":null},{\"topic_id\":204,\"action_tag\":\"identify\",\"text\":\"Identify effects of littering and careless resource use\",\"exam_relevance\":null},{\"topic_id\":204,\"action_tag\":\"describe\",\"text\":\"Describe effects of littering and careless resource use\",\"exam_relevance\":null},{\"topic_id\":206,\"action_tag\":\"identify\",\"text\":\"Identify simple map symbols and position words\",\"exam_relevance\":null},{\"topic_id\":206,\"action_tag\":\"use\",\"text\":\"Use simple map symbols and position words\",\"exam_relevance\":null},{\"topic_id\":206,\"action_tag\":\"draw\",\"text\":\"Draw a simple map of the classroom or school\",\"exam_relevance\":null},{\"topic_id\":206,\"action_tag\":\"label\",\"text\":\"Label a simple map of the classroom or school\",\"exam_relevance\":null},{\"topic_id\":207,\"action_tag\":\"describe\",\"text\":\"Describe daily weather using simple terms\",\"exam_relevance\":null},{\"topic_id\":207,\"action_tag\":\"record\",\"text\":\"Record daily weather using simple terms\",\"exam_relevance\":null},{\"topic_id\":207,\"action_tag\":\"explain\",\"text\":\"Explain how weather affects clothing and activities\",\"exam_relevance\":null},{\"topic_id\":207,\"action_tag\":\"compare\",\"text\":\"Compare how weather affects clothing and activities\",\"exam_relevance\":null}],\"approved_chunks\":[]},\"assessmentQuestionHistory\":[]}', '{\"raw\":\"{\\n  \\\"questions\\\": [\\n    {\\n      \\\"question_text\\\": \\\"Which of these is a natural feature?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"A school building\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"A river\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"A road\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"A bridge\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Natural features are things found in nature, not made by people. A river is a natural feature, while schools, roads, and bridges are human-made.\\\",\\n      \\\"common_mistake\\\": \\\"Confusing human-made structures with natural elements.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"classify\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Name two human-made features you can see in your local environment.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Accept any two valid human-made features such as: school, house, road, bridge, shop, park (if it has human-made structures like swings).\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"school\\\",\\n        \\\"house\\\",\\n        \\\"road\\\",\\n        \\\"bridge\\\",\\n        \\\"shop\\\",\\n        \\\"park\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Human-made features are structures or objects built by people. Examples include buildings, roads, and bridges.\\\",\\n      \\\"common_mistake\\\": \\\"Listing natural features instead of human-made ones.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"identify\\\",\\n      \\\"marks\\\": 2,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"What is the best way to care for your school environment?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Leaving rubbish on the floor\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Throwing waste in the bin\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"Drawing on the walls\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"Wasting water from the tap\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Throwing waste in the bin helps keep the school clean and tidy, which is an important way to care for the environment. The other options are harmful.\\\",\\n      \\\"common_mistake\\\": \\\"Not understanding the impact of littering or wasting resources.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"list\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Explain one reason why it is important to save water in our community.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Accept answers such as: To make sure there is enough water for everyone; To protect our natural resources; To prevent water shortages; To help the environment.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"To make sure there is enough water for everyone\\\",\\n        \\\"To protect our natural resources\\\",\\n        \\\"To prevent water shortages\\\",\\n        \\\"To help the environment\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Saving water ensures that there is enough for everyone in the community and helps protect this important natural resource for the future.\\\",\\n      \\\"common_mistake\\\": \\\"Giving a vague answer or not linking it to community benefit.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"explain\\\",\\n      \\\"marks\\\": 2,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Which symbol on a map usually represents a tree or a forest?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"A small square\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"A wavy line\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"A green shape like a tree\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"A straight line\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"C\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Map symbols are often simple drawings that look like the real-world feature they represent. A green tree-like shape is commonly used for trees or forests.\\\",\\n      \\\"common_mistake\\\": \\\"Confusing common map symbols or not understanding their representative nature.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"identify\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"If you are standing in front of your classroom door, and the teacher\'s desk is to your right, where is the window if it is behind the teacher\'s desk?\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"The window is behind you and to your right (or simply \'behind the teacher\'s desk\').\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"behind the teacher\'s desk\\\",\\n        \\\"behind you and to your right\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Using position words like \'right\' and \'behind\' helps us understand where things are located relative to each other.\\\",\\n      \\\"common_mistake\\\": \\\"Getting confused with multiple position words or relative directions.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"use\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.8\\n    },\\n    {\\n      \\\"question_text\\\": \\\"What kind of weather would you describe as having lots of dark clouds and drops of water falling from the sky?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Sunny\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Windy\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"Rainy\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"Cloudy\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"C\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Rainy weather is characterized by dark clouds and water falling from the sky. Cloudy weather has clouds but not necessarily rain.\\\",\\n      \\\"common_mistake\\\": \\\"Confusing \'cloudy\' with \'rainy\' if no rain is explicitly mentioned.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"describe\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Observe the weather outside your window right now. Describe it using two simple terms and suggest one activity you could do.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Accept any two accurate weather descriptions (e.g., \'sunny and warm\', \'cloudy and cool\', \'rainy and windy\') and one appropriate activity (e.g., \'play outside\', \'read a book indoors\', \'wear a raincoat and jump in puddles\').\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Being able to observe and describe daily weather helps us understand our environment and plan our activities accordingly.\\\",\\n      \\\"common_mistake\\\": \\\"Using complex terms or suggesting an activity that doesn\'t match the described weather.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"describe\\\",\\n      \\\"marks\\\": 3,\\n      \\\"confidence\\\": 0.85\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Is a hill a natural feature or a human-made feature?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Natural feature\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Human-made feature\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"Both natural and human-made\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"A\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"A hill is a raised area of land that occurs naturally, not built by people.\\\",\\n      \\\"common_mistake\\\": \\\"Confusing natural landforms with structures built on them.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"classify\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Look around your classroom. Identify one natural feature and one human-made feature.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Accept one natural feature (e.g., sunlight, air, a plant if present, view of trees outside) and one human-made feature (e.g., desk, chair, whiteboard, door, wall).\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Natural: sunlight, air, plant, view of trees. Human-made: desk, chair, whiteboard, door, wall.\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Even indoors, we can identify natural elements like light and air, alongside the many human-made objects that make up our environment.\\\",\\n      \\\"common_mistake\\\": \\\"Struggling to find natural features within an indoor setting or misclassifying items.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"identify\\\",\\n      \\\"marks\\\": 2,\\n      \\\"confidence\\\": 0.85\\n    },\\n    {\\n      \\\"question_text\\\": \\\"What is an effect of littering in our community?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Making places look beautiful\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Helping plants grow better\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"Making places look dirty and untidy\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"Attracting more visitors\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"C\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Littering makes our environment dirty and untidy, which can also harm animals and the environment.\\\",\\n      \\\"common_mistake\\\": \\\"Not understanding the negative consequences of littering.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"identify\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Describe one negative effect of wasting resources like paper or electricity.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Accept answers such as: It harms the environment; It means we might run out of resources; It costs more money; It creates more waste.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"It harms the environment\\\",\\n        \\\"It means we might run out of resources\\\",\\n        \\\"It costs more money\\\",\\n        \\\"It creates more waste\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Wasting resources can lead to environmental damage, depletion of natural materials, and increased costs.\\\",\\n      \\\"common_mistake\\\": \\\"Focusing only on personal inconvenience rather than broader environmental or economic impacts.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"describe\\\",\\n      \\\"marks\\\": 2,\\n      \\\"confidence\\\": 0.85\\n    },\\n    {\\n      \\\"question_text\\\": \\\"If a map shows a small blue rectangle, what might it represent?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"A mountain\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"A lake or pond\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"A road\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"A school\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Blue is commonly used on maps to represent water bodies like lakes, rivers, or ponds. A small rectangle could indicate a small body of water.\\\",\\n      \\\"common_mistake\\\": \\\"Not associating colors with common geographical features on maps.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"identify\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.8\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Imagine you are drawing a simple map of your bedroom. Draw a simple symbol for your bed and label it. Then, draw a symbol for your door and label it.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"A simple drawing of a bed (e.g., a rectangle with a pillow shape) labeled \'Bed\'. A simple drawing of a door (e.g., a rectangle with a small circle for a handle) labeled \'Door\'.\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Map symbols are simplified drawings that represent real-world objects. Labeling helps others understand what the symbols mean.\\\",\\n      \\\"common_mistake\\\": \\\"Drawing too much detail or forgetting to label the symbols.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"draw\\\",\\n      \\\"marks\\\": 4,\\n      \\\"confidence\\\": 0.85\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Why might you wear a warm jacket and hat on a very cold and windy day?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"To look fashionable\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"To stay warm and protect yourself from the cold\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"To make it harder to run\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"To carry more things\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Clothing choices are often made to suit the weather. Warm jackets and hats help keep us warm and protected when it\'s cold and windy.\\\",\\n      \\\"common_mistake\\\": \\\"Not connecting clothing directly to weather conditions and personal comfort/safety.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"explain\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Compare the type of clothing you would wear on a sunny day versus a rainy day.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"On a sunny day, you would wear light clothes like a t-shirt and shorts. On a rainy day, you would wear a raincoat, boots, and maybe carry an umbrella.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Sunny: light clothes, t-shirt, shorts. Rainy: raincoat, boots, umbrella.\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Different weather conditions require different clothing to keep us comfortable and protected. Sunny weather calls for light clothing, while rainy weather requires waterproof gear.\\\",\\n      \\\"common_mistake\\\": \\\"Only describing one type of weather or not making a clear comparison.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"compare\\\",\\n      \\\"marks\\\": 2,\\n      \\\"confidence\\\": 0.85\\n    },\\n    {\\n      \\\"question_text\\\": \\\"What is a \'natural feature\'?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"Something built by people\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"Something found in nature, not made by people\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"A type of animal\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"A drawing on a map\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"B\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Natural features are parts of the Earth\'s landscape that were formed by natural processes, such as mountains, rivers, and forests.\\\",\\n      \\\"common_mistake\\\": \\\"Confusing the definition with human-made features.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"define\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.9\\n    },\\n    {\\n      \\\"question_text\\\": \\\"List two ways you can help keep your local park clean and tidy.\\\",\\n      \\\"question_type\\\": \\\"short_answer\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Accept any two valid ways such as: Put rubbish in the bins; Don\'t pick flowers; Don\'t damage plants; Report broken equipment; Clean up after pets.\\\",\\n      \\\"accepted_answers_json\\\": [\\n        \\\"Put rubbish in the bins\\\",\\n        \\\"Don\'t pick flowers\\\",\\n        \\\"Don\'t damage plants\\\",\\n        \\\"Report broken equipment\\\",\\n        \\\"Clean up after pets\\\"\\n      ],\\n      \\\"explanation\\\": \\\"Caring for public spaces like parks ensures they remain pleasant and safe for everyone to enjoy.\\\",\\n      \\\"common_mistake\\\": \\\"Listing only one way or providing a general answer without specific actions.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"list\\\",\\n      \\\"marks\\\": 2,\\n      \\\"confidence\\\": 0.85\\n    },\\n    {\\n      \\\"question_text\\\": \\\"If the library is \'north\' of your classroom, and the playground is \'east\' of the library, where is the playground relative to your classroom?\\\",\\n      \\\"question_type\\\": \\\"multiple_choice\\\",\\n      \\\"options_json\\\": [\\n        {\\n          \\\"label\\\": \\\"A\\\",\\n          \\\"text\\\": \\\"North-east\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"B\\\",\\n          \\\"text\\\": \\\"South-west\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"C\\\",\\n          \\\"text\\\": \\\"North-west\\\"\\n        },\\n        {\\n          \\\"label\\\": \\\"D\\\",\\n          \\\"text\\\": \\\"South-east\\\"\\n        }\\n      ],\\n      \\\"correct_answer\\\": \\\"A\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"If the library is north, and the playground is east of the library, then from the classroom, the playground would be in the north-east direction.\\\",\\n      \\\"common_mistake\\\": \\\"Getting confused with compound directions or relative positioning.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"use\\\",\\n      \\\"marks\\\": 1,\\n      \\\"confidence\\\": 0.8\\n    },\\n    {\\n      \\\"question_text\\\": \\\"Imagine you are a weather reporter for your school. For tomorrow, predict the weather using simple terms (e.g., sunny, cloudy, rainy, windy) and explain what you would advise students to wear.\\\",\\n      \\\"question_type\\\": \\\"structured\\\",\\n      \\\"options_json\\\": [],\\n      \\\"correct_answer\\\": \\\"Accept a clear weather prediction (e.g., \'Tomorrow will be sunny and warm.\') and appropriate clothing advice (e.g., \'Wear light clothes like t-shirts and shorts, and don\'t forget your hats!\').\\\",\\n      \\\"accepted_answers_json\\\": [],\\n      \\\"explanation\\\": \\\"Weather observations help us predict future conditions and make practical decisions, such as choosing appropriate clothing.\\\",\\n      \\\"common_mistake\\\": \\\"Not providing both a weather description and clothing advice, or giving advice that doesn\'t match the predicted weather.\\\",\\n      \\\"difficulty\\\": \\\"easy\\\",\\n      \\\"skill_type\\\": \\\"explain\\\",\\n      \\\"marks\\\": 3,\\n      \\\"confidence\\\": 0.85\\n    }\\n  ]\\n}\",\"data\":{\"questions\":[{\"question_text\":\"Which of these is a natural feature?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"A school building\"},{\"label\":\"B\",\"text\":\"A river\"},{\"label\":\"C\",\"text\":\"A road\"},{\"label\":\"D\",\"text\":\"A bridge\"}],\"correct_answer\":\"B\",\"accepted_answers\":[],\"explanation\":\"Natural features are things found in nature, not made by people. A river is a natural feature, while schools, roads, and bridges are human-made.\",\"common_mistake\":\"Confusing human-made structures with natural elements.\",\"difficulty\":\"easy\",\"skill_type\":\"classify\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"Name two human-made features you can see in your local environment.\",\"question_type\":\"short_answer\",\"options\":[],\"correct_answer\":\"Accept any two valid human-made features such as: school, house, road, bridge, shop, park (if it has human-made structures like swings).\",\"accepted_answers\":[\"school\",\"house\",\"road\",\"bridge\",\"shop\",\"park\"],\"explanation\":\"Human-made features are structures or objects built by people. Examples include buildings, roads, and bridges.\",\"common_mistake\":\"Listing natural features instead of human-made ones.\",\"difficulty\":\"easy\",\"skill_type\":\"identify\",\"marks\":2,\"confidence\":0.9},{\"question_text\":\"What is the best way to care for your school environment?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"Leaving rubbish on the floor\"},{\"label\":\"B\",\"text\":\"Throwing waste in the bin\"},{\"label\":\"C\",\"text\":\"Drawing on the walls\"},{\"label\":\"D\",\"text\":\"Wasting water from the tap\"}],\"correct_answer\":\"B\",\"accepted_answers\":[],\"explanation\":\"Throwing waste in the bin helps keep the school clean and tidy, which is an important way to care for the environment. The other options are harmful.\",\"common_mistake\":\"Not understanding the impact of littering or wasting resources.\",\"difficulty\":\"easy\",\"skill_type\":\"list\",\"marks\":1,\"confidence\":0.9},{\"question_text\":\"Explain one reason why it is important to save water in our community.\",\"question_type\":\"short_answer\",\"options\":[],\"correct_answer\":\"Accept answers such as: To make sure there is enough water for everyone; To protect our natural resources; To prevent water shortages; To help the environment.\",\"accepted_answers\":[\"To make sure there is enough water for everyone\",\"To protect our natural resources\",\"To prevent water shortages\",\"To help the environment\"],\"explanation\":\"Saving water ensures that there is enough for everyone in the community and helps protect this important natural resource for the future.\",\"common_mistake\":\"Giving a vague answer or not linking it to community benefit.\",\"difficulty\":\"easy\",\"skill_type\":\"explain\",\"marks\":2,\"confidence\":0.9},{\"question_text\":\"Which symbol on a map usually represents a tree or a forest?\",\"question_type\":\"multiple_choice\",\"options\":[{\"label\":\"A\",\"text\":\"A small square\"},{\"label\":\"B\",\"text\":\"A wavy line\"},{\"label\":\"C\",\"text\":\"A green shape like a tree\"},{\"label\":\"D\",\"text\":\"A straight line\"}],\"correct_answer\":\"C\",\"accepted_answers\":[],\"explanation\":\"Map symbols are often simple drawings that look like the real-world feature they represent. A green tree-like shape is commonly used for trees or forests.\",\"common_mistake\":\"Confusing common map symbols or not 