INSERT INTO `manual_syllabus_entries` (`id`, `school_id`, `submitted_by`, `reviewed_by`, `curriculum_id`, `grade_id`, `subject_id`, `term`, `suggested_week`, `topic_name`, `description`, `objectives_json`, `status`, `review_notes`, `approved_topic_id`, `submitted_at`, `reviewed_at`, `created_at`, `updated_at`) VALUES
(4, 1, 32, 32, 9, 35, 31, 'Term 3', NULL, 'Agricultural Economics and Far Business', NULL, '{\"flat_objectives\":[],\"subtopics\":[{\"title\":\"Marketing Factors\",\"notes\":null,\"criteria\":[{\"action\":\"define\",\"actions\":[\"define\",\"list\",\"explain\",\"identify\"],\"label\":\"Define\",\"labels\":[\"Define\",\"List\",\"Explain\",\"Identify\"],\"detail\":\"main factors of agricultural production\",\"text\":\"Define, List, Explain, Identify main factors of agricultural production\"}]}]}', 'approved', NULL, 136, '2026-06-20 16:14:51', '2026-06-20 16:16:04', '2026-06-20 16:14:51', '2026-06-20 16:16:04'),
(5, 1, 36, 32, 9, 37, 31, NULL, NULL, 'Year 3 Agriculture Syllabus', 'Standing Cambridge Primary Year 3 Agriculture syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Agricultural Production\",\"notes\":\"Introduces the main resources and decisions involved in producing food at home and school.\",\"subtopics\":[{\"title\":\"Factors of Production\",\"notes\":\"Land, labour, capital, management and simple examples from local farming.\",\"criteria\":[{\"actions\":[\"define\",\"list\"],\"detail\":\"the main factors of agricultural production\"},{\"actions\":[\"explain\",\"identify\"],\"detail\":\"how land, labour, capital and management help a farmer produce crops\"}]},{\"title\":\"Farm Tools and Safety\",\"notes\":\"Common hand tools, safe handling and proper storage after use.\",\"criteria\":[{\"actions\":[\"identify\",\"describe\"],\"detail\":\"common farm tools and their uses\"},{\"actions\":[\"explain\",\"list\"],\"detail\":\"safety rules for using and storing farm tools\"}]}]},{\"title\":\"Soil and Crops\",\"notes\":\"Basic soil properties and crop care practices suitable for Year 3 learners.\",\"subtopics\":[{\"title\":\"Soil Types\",\"notes\":\"Clay, sand and loam; simple observation of texture and water holding.\",\"criteria\":[{\"actions\":[\"define\",\"compare\"],\"detail\":\"sand, clay and loam soils using simple properties\"},{\"actions\":[\"explain\",\"identify\"],\"detail\":\"which soil is suitable for growing common crops\"}]},{\"title\":\"Caring for Crops\",\"notes\":\"Watering, weeding, mulching and protecting young plants.\",\"criteria\":[{\"actions\":[\"list\",\"describe\"],\"detail\":\"ways of caring for crops after planting\"},{\"actions\":[\"explain\",\"apply\"],\"detail\":\"why watering and weeding improve crop growth\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 138, '2026-06-21 07:13:19', '2026-06-21 07:35:39', '2026-06-21 07:13:19', '2026-06-21 07:35:39'),
(6, 1, 36, 32, 9, 37, 33, NULL, NULL, 'Year 3 Bible Knowledge Syllabus', 'Standing Cambridge Primary Year 3 Bible Knowledge syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Bible Stories and Values\",\"notes\":\"Learners explore familiar Bible stories and connect them to kindness, honesty and obedience.\",\"subtopics\":[{\"title\":\"Creation and Care\",\"notes\":\"Creation story and responsible care for people, animals and the environment.\",\"criteria\":[{\"actions\":[\"retell\",\"list\"],\"detail\":\"the main events in the creation story\"},{\"actions\":[\"explain\",\"identify\"],\"detail\":\"ways learners can care for creation at school and home\"}]},{\"title\":\"Stories of Kindness\",\"notes\":\"Bible examples of helping others and showing respect.\",\"criteria\":[{\"actions\":[\"describe\",\"identify\"],\"detail\":\"acts of kindness shown in a Bible story\"},{\"actions\":[\"apply\",\"explain\"],\"detail\":\"how a learner can show kindness in daily life\"}]}]},{\"title\":\"Prayer and Worship\",\"notes\":\"Simple forms of prayer, praise and respectful participation.\",\"subtopics\":[{\"title\":\"Why People Pray\",\"notes\":\"Prayer as thanks, request, praise and confession.\",\"criteria\":[{\"actions\":[\"define\",\"list\"],\"detail\":\"simple purposes of prayer\"},{\"actions\":[\"explain\",\"give_examples\"],\"detail\":\"when people may pray\"}]},{\"title\":\"Respect in Worship\",\"notes\":\"Respectful behaviour during worship and religious gatherings.\",\"criteria\":[{\"actions\":[\"identify\",\"describe\"],\"detail\":\"respectful behaviours during worship\"},{\"actions\":[\"explain\",\"state\"],\"detail\":\"why people should respect places of worship\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 145, '2026-06-21 07:13:19', '2026-06-21 07:36:29', '2026-06-21 07:13:19', '2026-06-21 07:36:29'),
(7, 1, 36, 32, 9, 37, 21, NULL, NULL, 'Year 3 Biology Syllabus', 'Standing Cambridge Primary Year 3 Biology syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Living Things\",\"notes\":\"Learners observe living and non-living things and their basic needs.\",\"subtopics\":[{\"title\":\"Characteristics of Living Things\",\"notes\":\"Growth, feeding, breathing, movement and reproduction in simple language.\",\"criteria\":[{\"actions\":[\"define\",\"list\"],\"detail\":\"characteristics of living things\"},{\"actions\":[\"classify\",\"explain\"],\"detail\":\"objects as living or non-living using evidence\"}]},{\"title\":\"Needs of Plants and Animals\",\"notes\":\"Food, water, air, shelter, light and care.\",\"criteria\":[{\"actions\":[\"identify\",\"list\"],\"detail\":\"basic needs of plants and animals\"},{\"actions\":[\"explain\",\"compare\"],\"detail\":\"how plant needs and animal needs are similar and different\"}]}]},{\"title\":\"Plants and Animals\",\"notes\":\"Simple plant parts, animal groups and habitats.\",\"subtopics\":[{\"title\":\"Parts of a Plant\",\"notes\":\"Roots, stem, leaves, flowers and fruit with simple functions.\",\"criteria\":[{\"actions\":[\"identify\",\"label\"],\"detail\":\"the main parts of a plant\"},{\"actions\":[\"explain\",\"describe\"],\"detail\":\"the function of roots, stem and leaves\"}]},{\"title\":\"Habitats\",\"notes\":\"Homes of animals and how habitats provide needs.\",\"criteria\":[{\"actions\":[\"define\",\"give_examples\"],\"detail\":\"habitats found in the local environment\"},{\"actions\":[\"explain\",\"match\"],\"detail\":\"animals to suitable habitats\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 159, '2026-06-21 07:13:19', '2026-06-21 07:36:46', '2026-06-21 07:13:19', '2026-06-21 07:36:46'),
(8, 1, 36, 32, 9, 37, 23, NULL, NULL, 'Year 3 Chemistry Syllabus', 'Standing Cambridge Primary Year 3 Chemistry syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Materials Around Us\",\"notes\":\"Common materials and simple observable properties.\",\"subtopics\":[{\"title\":\"Types of Materials\",\"notes\":\"Wood, metal, plastic, glass, fabric and paper in everyday objects.\",\"criteria\":[{\"actions\":[\"identify\",\"list\"],\"detail\":\"common materials used to make everyday objects\"},{\"actions\":[\"classify\",\"explain\"],\"detail\":\"objects by the material they are made from\"}]},{\"title\":\"Properties of Materials\",\"notes\":\"Hard, soft, strong, flexible, waterproof and transparent.\",\"criteria\":[{\"actions\":[\"define\",\"describe\"],\"detail\":\"simple properties of materials\"},{\"actions\":[\"compare\",\"select\"],\"detail\":\"suitable materials for simple purposes\"}]}]},{\"title\":\"Changes in Materials\",\"notes\":\"Heating, cooling, mixing and reversible changes using safe examples.\",\"subtopics\":[{\"title\":\"Melting and Freezing\",\"notes\":\"Ice, water, butter and wax as simple examples.\",\"criteria\":[{\"actions\":[\"define\",\"describe\"],\"detail\":\"melting and freezing using everyday examples\"},{\"actions\":[\"explain\",\"predict\"],\"detail\":\"what happens to water when it is heated or cooled\"}]},{\"title\":\"Safe Mixing\",\"notes\":\"Safe mixtures such as water with salt, sugar or soil.\",\"criteria\":[{\"actions\":[\"observe\",\"describe\"],\"detail\":\"what happens when safe materials are mixed with water\"},{\"actions\":[\"state\",\"explain\"],\"detail\":\"basic safety rules for handling materials\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 229, '2026-06-21 07:13:19', '2026-06-21 07:37:49', '2026-06-21 07:13:19', '2026-06-21 07:37:49'),
(9, 1, 36, 32, 9, 37, 5, NULL, NULL, 'Year 3 Chichewa Syllabus', 'Standing Cambridge Primary Year 3 Chichewa syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Kumvetsera ndi Kulankhula\",\"notes\":\"Kumvetsera malangizo, kuyankha mafunso ndi kulankhula momveka bwino.\",\"subtopics\":[{\"title\":\"Kumvetsera Malangizo\",\"notes\":\"Ana amatsatira malangizo a mkalasi ndi nkhani zazifupi.\",\"criteria\":[{\"actions\":[\"identify\",\"explain\"],\"detail\":\"mfundo zazikulu mu nkhani yomwe yamvedwa\"},{\"actions\":[\"follow\",\"list\"],\"detail\":\"malangizo awiri kapena atatu operekedwa m_Chichewa\"}]},{\"title\":\"Kulankhula Mwaulemu\",\"notes\":\"Kugwiritsa ntchito moni, kuyamika ndi kupempha zinthu mwaulemu.\",\"criteria\":[{\"actions\":[\"state\",\"use\"],\"detail\":\"mawu a ulemu pa zokambirana za tsiku ndi tsiku\"},{\"actions\":[\"describe\",\"demonstrate\"],\"detail\":\"momwe tingayankhulire mwaulemu kwa akulu ndi anzathu\"}]}]},{\"title\":\"Kuwerenga ndi Kulemba\",\"notes\":\"Kuwerenga mawu, ziganizo ndi kulemba ndime zazifupi.\",\"subtopics\":[{\"title\":\"Kuwerenga Mawu ndi Ziganizo\",\"notes\":\"Mawu odziwika, ziganizo zosavuta ndi kumvetsa tanthauzo.\",\"criteria\":[{\"actions\":[\"read\",\"identify\"],\"detail\":\"mawu ofunika mu ziganizo zosavuta\"},{\"actions\":[\"explain\",\"answer\"],\"detail\":\"mafunso okhudza zomwe zawerengedwa\"}]},{\"title\":\"Kulemba Ndime Yachifupi\",\"notes\":\"Kulemba ndime yokhala ndi mutu, ziganizo ndi mapeto.\",\"criteria\":[{\"actions\":[\"write\",\"create\"],\"detail\":\"ndime yachifupi yokhudza banja, sukulu kapena mudzi\"},{\"actions\":[\"use\",\"identify\"],\"detail\":\"zizindikiro zosavuta monga full stop ndi question mark\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 222, '2026-06-21 07:13:19', '2026-06-21 07:37:44', '2026-06-21 07:13:19', '2026-06-21 07:37:44'),
(10, 1, 36, 32, 9, 37, 35, NULL, NULL, 'Year 3 Computer Studies Syllabus', 'Standing Cambridge Primary Year 3 Computer Studies syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Computer Basics\",\"notes\":\"Parts of a computer and simple safe use routines.\",\"subtopics\":[{\"title\":\"Parts of a Computer\",\"notes\":\"Monitor, keyboard, mouse, system unit and speakers.\",\"criteria\":[{\"actions\":[\"identify\",\"label\"],\"detail\":\"main parts of a desktop computer\"},{\"actions\":[\"explain\",\"match\"],\"detail\":\"computer parts to their basic functions\"}]},{\"title\":\"Using Input Devices\",\"notes\":\"Mouse clicks, keyboard keys and simple typing practice.\",\"criteria\":[{\"actions\":[\"describe\",\"demonstrate\"],\"detail\":\"safe use of a mouse and keyboard\"},{\"actions\":[\"list\",\"apply\"],\"detail\":\"steps for opening and closing a simple program\"}]}]},{\"title\":\"Digital Safety and Creation\",\"notes\":\"Responsible use of devices and creating simple digital work.\",\"subtopics\":[{\"title\":\"Safe Computer Use\",\"notes\":\"Posture, sharing devices, passwords and asking an adult for help.\",\"criteria\":[{\"actions\":[\"list\",\"explain\"],\"detail\":\"rules for safe and responsible computer use\"},{\"actions\":[\"identify\",\"state\"],\"detail\":\"private information that should not be shared\"}]},{\"title\":\"Creating Simple Documents\",\"notes\":\"Typing, editing and adding a title to simple class work.\",\"criteria\":[{\"actions\":[\"create\",\"format\"],\"detail\":\"a simple document with a title and short sentences\"},{\"actions\":[\"save\",\"explain\"],\"detail\":\"why files should be saved with clear names\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 215, '2026-06-21 07:13:19', '2026-06-21 07:37:39', '2026-06-21 07:13:19', '2026-06-21 07:37:39'),
(11, 1, 36, 32, 9, 37, 3, NULL, NULL, 'Year 3 English Syllabus', 'Standing Cambridge Primary Year 3 English syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Reading and Comprehension\",\"notes\":\"Reading short texts for meaning, details and sequence.\",\"subtopics\":[{\"title\":\"Main Idea and Details\",\"notes\":\"Finding what a text is mostly about and supporting details.\",\"criteria\":[{\"actions\":[\"identify\",\"explain\"],\"detail\":\"the main idea in a short passage\"},{\"actions\":[\"list\",\"select\"],\"detail\":\"details that support the main idea\"}]},{\"title\":\"Sequencing Events\",\"notes\":\"Beginning, middle and end of a story or factual text.\",\"criteria\":[{\"actions\":[\"order\",\"retell\"],\"detail\":\"events from a short story in the correct sequence\"},{\"actions\":[\"explain\",\"use\"],\"detail\":\"time words such as first, next and finally\"}]}]},{\"title\":\"Grammar and Writing\",\"notes\":\"Sentence building and short paragraph writing.\",\"subtopics\":[{\"title\":\"Sentences and Punctuation\",\"notes\":\"Capital letters, full stops, question marks and sentence sense.\",\"criteria\":[{\"actions\":[\"identify\",\"correct\"],\"detail\":\"capital letters and ending punctuation in sentences\"},{\"actions\":[\"write\",\"create\"],\"detail\":\"clear sentences about familiar topics\"}]},{\"title\":\"Descriptive Writing\",\"notes\":\"Using adjectives and simple paragraph structure.\",\"criteria\":[{\"actions\":[\"define\",\"use\"],\"detail\":\"adjectives to describe people, places and objects\"},{\"actions\":[\"write\",\"organise\"],\"detail\":\"a short descriptive paragraph with related ideas\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 208, '2026-06-21 07:13:19', '2026-06-21 07:37:30', '2026-06-21 07:13:19', '2026-06-21 07:37:30'),
(12, 1, 36, 32, 9, 37, 27, NULL, NULL, 'Year 3 Geography Syllabus', 'Standing Cambridge Primary Year 3 Geography syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Local Environment\",\"notes\":\"Physical and human features learners can observe around them.\",\"subtopics\":[{\"title\":\"Natural and Human Features\",\"notes\":\"Rivers, hills, roads, schools, bridges and homes.\",\"criteria\":[{\"actions\":[\"define\",\"classify\"],\"detail\":\"natural features and human-made features\"},{\"actions\":[\"identify\",\"describe\"],\"detail\":\"features found in the local environment\"}]},{\"title\":\"Caring for Places\",\"notes\":\"Keeping spaces clean and protecting natural resources.\",\"criteria\":[{\"actions\":[\"list\",\"explain\"],\"detail\":\"ways to care for the school and community environment\"},{\"actions\":[\"identify\",\"describe\"],\"detail\":\"effects of littering and careless resource use\"}]}]},{\"title\":\"Maps, Direction and Weather\",\"notes\":\"Simple map symbols, directions and daily weather observations.\",\"subtopics\":[{\"title\":\"Simple Maps\",\"notes\":\"Classroom maps, symbols and position words.\",\"criteria\":[{\"actions\":[\"identify\",\"use\"],\"detail\":\"simple map symbols and position words\"},{\"actions\":[\"draw\",\"label\"],\"detail\":\"a simple map of the classroom or school\"}]},{\"title\":\"Weather Observation\",\"notes\":\"Sunny, cloudy, rainy and windy weather with basic recording.\",\"criteria\":[{\"actions\":[\"describe\",\"record\"],\"detail\":\"daily weather using simple terms\"},{\"actions\":[\"explain\",\"compare\"],\"detail\":\"how weather affects clothing and activities\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 201, '2026-06-21 07:13:19', '2026-06-21 07:37:26', '2026-06-21 07:13:19', '2026-06-21 07:37:26'),
(13, 1, 36, 32, 9, 37, 29, NULL, NULL, 'Year 3 History Syllabus', 'Standing Cambridge Primary Year 3 History syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Family and Community History\",\"notes\":\"Personal timelines, family stories and community memories.\",\"subtopics\":[{\"title\":\"Personal Timelines\",\"notes\":\"Ordering events from birth to present using time words.\",\"criteria\":[{\"actions\":[\"order\",\"describe\"],\"detail\":\"important events on a simple personal timeline\"},{\"actions\":[\"use\",\"explain\"],\"detail\":\"past and present time words correctly\"}]},{\"title\":\"Sources of History\",\"notes\":\"Stories, photographs, objects and buildings as evidence about the past.\",\"criteria\":[{\"actions\":[\"define\",\"identify\"],\"detail\":\"simple sources that tell us about the past\"},{\"actions\":[\"explain\",\"compare\"],\"detail\":\"how different sources help us learn history\"}]}]},{\"title\":\"Change Over Time\",\"notes\":\"How schools, homes, transport and communication have changed.\",\"subtopics\":[{\"title\":\"Then and Now\",\"notes\":\"Comparing past and present tools, clothing, transport and school life.\",\"criteria\":[{\"actions\":[\"compare\",\"describe\"],\"detail\":\"similarities and differences between past and present life\"},{\"actions\":[\"identify\",\"explain\"],\"detail\":\"reasons why some things change over time\"}]},{\"title\":\"Important Community Places\",\"notes\":\"Local landmarks and why people remember them.\",\"criteria\":[{\"actions\":[\"identify\",\"describe\"],\"detail\":\"important places in the community\"},{\"actions\":[\"explain\",\"state\"],\"detail\":\"why people preserve important places\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 194, '2026-06-21 07:13:19', '2026-06-21 07:37:18', '2026-06-21 07:13:19', '2026-06-21 07:37:18'),
(14, 1, 36, 32, 9, 37, 2, NULL, NULL, 'Year 3 Mathematics Syllabus', 'Standing Cambridge Primary Year 3 Mathematics syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Number and Operations\",\"notes\":\"Place value, comparing numbers and the four operations at Year 3 level.\",\"subtopics\":[{\"title\":\"Place Value\",\"notes\":\"Hundreds, tens and ones; reading and writing numbers.\",\"criteria\":[{\"actions\":[\"identify\",\"represent\"],\"detail\":\"the value of digits in three-digit numbers\"},{\"actions\":[\"compare\",\"order\"],\"detail\":\"numbers up to 1000 using place value\"}]},{\"title\":\"Addition and Subtraction\",\"notes\":\"Mental and written strategies for solving familiar problems.\",\"criteria\":[{\"actions\":[\"calculate\",\"explain\"],\"detail\":\"addition and subtraction problems using suitable strategies\"},{\"actions\":[\"apply\",\"solve\"],\"detail\":\"word problems involving addition and subtraction\"}]}]},{\"title\":\"Measurement and Geometry\",\"notes\":\"Length, mass, capacity, time and 2D/3D shapes.\",\"subtopics\":[{\"title\":\"Measuring Objects\",\"notes\":\"Using standard units and choosing sensible measuring tools.\",\"criteria\":[{\"actions\":[\"select\",\"use\"],\"detail\":\"appropriate units and tools for measuring length, mass and capacity\"},{\"actions\":[\"compare\",\"estimate\"],\"detail\":\"measurements of everyday objects\"}]},{\"title\":\"Shapes and Patterns\",\"notes\":\"Properties of 2D shapes, simple 3D objects and repeating patterns.\",\"criteria\":[{\"actions\":[\"identify\",\"describe\"],\"detail\":\"properties of common 2D and 3D shapes\"},{\"actions\":[\"create\",\"continue\"],\"detail\":\"shape and number patterns using a rule\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 187, '2026-06-21 07:13:19', '2026-06-21 07:37:12', '2026-06-21 07:13:19', '2026-06-21 07:37:12'),
(15, 1, 36, 32, 9, 37, 25, NULL, NULL, 'Year 3 Physics Syllabus', 'Standing Cambridge Primary Year 3 Physics syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Forces and Movement\",\"notes\":\"Pushes, pulls, speed and simple effects of forces.\",\"subtopics\":[{\"title\":\"Pushes and Pulls\",\"notes\":\"Everyday examples of forces starting, stopping or changing movement.\",\"criteria\":[{\"actions\":[\"define\",\"identify\"],\"detail\":\"push and pull forces in everyday activities\"},{\"actions\":[\"explain\",\"predict\"],\"detail\":\"how a force can change the movement of an object\"}]},{\"title\":\"Friction\",\"notes\":\"How surfaces affect movement in simple investigations.\",\"criteria\":[{\"actions\":[\"describe\",\"compare\"],\"detail\":\"movement of objects on rough and smooth surfaces\"},{\"actions\":[\"explain\",\"investigate\"],\"detail\":\"how friction affects motion\"}]}]},{\"title\":\"Light and Sound\",\"notes\":\"Sources of light and sound, shadows and safe listening.\",\"subtopics\":[{\"title\":\"Light and Shadows\",\"notes\":\"Light sources, blocking light and shadow formation.\",\"criteria\":[{\"actions\":[\"identify\",\"classify\"],\"detail\":\"sources of light and non-light sources\"},{\"actions\":[\"explain\",\"predict\"],\"detail\":\"how shadows are formed\"}]},{\"title\":\"Sound Sources\",\"notes\":\"Vibrations, loud and soft sounds and protecting ears.\",\"criteria\":[{\"actions\":[\"identify\",\"describe\"],\"detail\":\"sources of sound in the environment\"},{\"actions\":[\"explain\",\"state\"],\"detail\":\"ways to protect hearing from very loud sounds\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 180, '2026-06-21 07:13:20', '2026-06-21 07:37:06', '2026-06-21 07:13:20', '2026-06-21 07:37:06'),
(16, 1, 36, 32, 9, 37, 4, NULL, NULL, 'Year 3 Science Syllabus', 'Standing Cambridge Primary Year 3 Science syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Working Scientifically\",\"notes\":\"Asking questions, observing carefully and recording simple findings.\",\"subtopics\":[{\"title\":\"Observation and Questions\",\"notes\":\"Using senses and simple tools to observe safely.\",\"criteria\":[{\"actions\":[\"ask\",\"identify\"],\"detail\":\"scientific questions about familiar objects and events\"},{\"actions\":[\"observe\",\"record\"],\"detail\":\"simple observations using words, drawings or tables\"}]},{\"title\":\"Fair Tests\",\"notes\":\"Changing one thing at a time in simple investigations.\",\"criteria\":[{\"actions\":[\"define\",\"explain\"],\"detail\":\"a fair test in simple language\"},{\"actions\":[\"plan\",\"identify\"],\"detail\":\"what to keep the same and what to change in an investigation\"}]}]},{\"title\":\"Earth and Sky\",\"notes\":\"Day and night, weather, soil and natural resources.\",\"subtopics\":[{\"title\":\"Day and Night\",\"notes\":\"Observable changes during day and night.\",\"criteria\":[{\"actions\":[\"describe\",\"compare\"],\"detail\":\"features of daytime and nighttime\"},{\"actions\":[\"explain\",\"identify\"],\"detail\":\"activities suited to day and night\"}]},{\"title\":\"Natural Resources\",\"notes\":\"Water, soil, air, plants and responsible use.\",\"criteria\":[{\"actions\":[\"define\",\"list\"],\"detail\":\"natural resources used by people\"},{\"actions\":[\"explain\",\"suggest\"],\"detail\":\"ways to use natural resources responsibly\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 173, '2026-06-21 07:13:20', '2026-06-21 07:37:00', '2026-06-21 07:13:20', '2026-06-21 07:37:00'),
(17, 1, 36, 32, 9, 37, 19, NULL, NULL, 'Year 3 Science and Technology Syllabus', 'Standing Cambridge Primary Year 3 Science and Technology syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Designing and Making\",\"notes\":\"Solving simple problems by planning, making and improving models.\",\"subtopics\":[{\"title\":\"Design Process\",\"notes\":\"Ask, imagine, plan, make, test and improve.\",\"criteria\":[{\"actions\":[\"list\",\"explain\"],\"detail\":\"steps in a simple design process\"},{\"actions\":[\"apply\",\"create\"],\"detail\":\"a simple solution for a classroom or home problem\"}]},{\"title\":\"Testing and Improving\",\"notes\":\"Checking whether a model works and changing it based on evidence.\",\"criteria\":[{\"actions\":[\"test\",\"record\"],\"detail\":\"whether a simple model works as planned\"},{\"actions\":[\"explain\",\"improve\"],\"detail\":\"changes that make a design better\"}]}]},{\"title\":\"Tools, Materials and Technology\",\"notes\":\"Choosing safe tools and understanding technology in daily life.\",\"subtopics\":[{\"title\":\"Choosing Materials\",\"notes\":\"Selecting materials by strength, flexibility and waterproofing.\",\"criteria\":[{\"actions\":[\"compare\",\"select\"],\"detail\":\"materials for a simple design task\"},{\"actions\":[\"explain\",\"justify\"],\"detail\":\"why a chosen material suits a purpose\"}]},{\"title\":\"Technology Around Us\",\"notes\":\"How everyday technologies help people work, learn and communicate.\",\"criteria\":[{\"actions\":[\"identify\",\"describe\"],\"detail\":\"technologies used at home, school and in the community\"},{\"actions\":[\"explain\",\"evaluate\"],\"detail\":\"benefits and careful use of everyday technology\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 166, '2026-06-21 07:13:20', '2026-06-21 07:36:53', '2026-06-21 07:13:20', '2026-06-21 07:36:53'),
(18, 1, 36, 32, 9, 37, 6, NULL, NULL, 'Year 3 Social Studies Syllabus', 'Standing Cambridge Primary Year 3 Social Studies syllabus for teacher review. It is not term-specific and can be tweaked when the school updates the document.', '{\"flat_objectives\":[],\"topics\":[{\"title\":\"Community and Citizenship\",\"notes\":\"Roles, responsibilities and respectful participation in the community.\",\"subtopics\":[{\"title\":\"Community Helpers\",\"notes\":\"People who help the community and the services they provide.\",\"criteria\":[{\"actions\":[\"identify\",\"describe\"],\"detail\":\"community helpers and their roles\"},{\"actions\":[\"explain\",\"match\"],\"detail\":\"services provided by different community helpers\"}]},{\"title\":\"Rights and Responsibilities\",\"notes\":\"Simple rights and duties at school, home and community level.\",\"criteria\":[{\"actions\":[\"define\",\"list\"],\"detail\":\"simple rights and responsibilities of children\"},{\"actions\":[\"explain\",\"apply\"],\"detail\":\"responsible behaviour in school and community settings\"}]}]},{\"title\":\"Resources and Wellbeing\",\"notes\":\"Using resources wisely and making healthy community choices.\",\"subtopics\":[{\"title\":\"Needs and Wants\",\"notes\":\"Basic needs, wants and careful choices.\",\"criteria\":[{\"actions\":[\"define\",\"compare\"],\"detail\":\"needs and wants using everyday examples\"},{\"actions\":[\"classify\",\"explain\"],\"detail\":\"items as needs or wants\"}]},{\"title\":\"Healthy Communities\",\"notes\":\"Clean water, sanitation, cooperation and safety.\",\"criteria\":[{\"actions\":[\"list\",\"describe\"],\"detail\":\"features of a healthy community\"},{\"actions\":[\"suggest\",\"explain\"],\"detail\":\"ways learners can help keep the community healthy\"}]}]}],\"subtopics\":[]}', 'approved', NULL, 152, '2026-06-21 07:13:20', '2026-06-21 07:36:41', '2026-06-21 07:13:20', '2026-06-21 07:36:41'),
(21, 3, 137, 137, 16, 76, 65, NULL, NULL, 'Year 1 Agriculture', 'Generated from approved Full Syllabus extraction. Source: Grade3_Agriculture_Syllabus.pdf', '{\"flat_objectives\":[],\"subtopics\":[],\"topics\":[{\"title\":\"Introduction to Agriculture\",\"notes\":\"This unit introduces learners to the fundamental concepts of agriculture, its importance in daily life, and the various types of agricultural activities practiced in their community.\",\"criteria\":[],\"subtopics\":[{\"title\":\"Meaning and Importance of Agriculture\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"explain\"],\"detail\":\"the meaning of agriculture in their own words\",\"text\":\"Explain the meaning of agriculture in their own words\"},{\"actions\":[\"list\"],\"detail\":\"three reasons why agriculture is important\",\"text\":\"List three reasons why agriculture is important\"},{\"actions\":[\"identify\"],\"detail\":\"examples of agricultural activities happening around their home\",\"text\":\"Identify examples of agricultural activities happening around their home\"}]},{\"title\":\"Types of Agricultural Activities\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"identify\",\"define\"],\"detail\":\"the four main types of agricultural activities\",\"text\":\"Identify the four main types of agricultural activities\"},{\"actions\":[\"compare\"],\"detail\":\"pictures of farming activities to their correct type\",\"text\":\"Compare pictures of farming activities to their correct type\"},{\"actions\":[\"describe\"],\"detail\":\"one activity from each type of agriculture\",\"text\":\"Describe one activity from each type of agriculture\"}]}]},{\"title\":\"The School and Home Garden\",\"notes\":\"This unit focuses on practical skills for preparing and planting a garden, emphasizing hands-on activities relevant to school and home environments.\",\"criteria\":[],\"subtopics\":[{\"title\":\"Preparing a Garden\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"describe\",\"create\"],\"detail\":\"the steps taken to prepare a garden\",\"text\":\"Describe the steps taken to prepare a garden\"},{\"actions\":[\"apply\"],\"detail\":\"safe practices to clear a small plot of land\",\"text\":\"Apply safe practices to clear a small plot of land\"},{\"actions\":[\"create\"],\"detail\":\"a simple garden bed with guidance\",\"text\":\"Create a simple garden bed with guidance\"}]},{\"title\":\"Planting\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"apply\"],\"detail\":\"correct spacing and depth when planting seeds\",\"text\":\"Apply correct spacing and depth when planting seeds\"},{\"actions\":[\"explain\"],\"detail\":\"the importance of correct seed spacing\",\"text\":\"Explain the importance of correct seed spacing\"},{\"actions\":[\"identify\"],\"detail\":\"good seeds from poor seeds\",\"text\":\"Identify good seeds from poor seeds\"}]}]},{\"title\":\"Crop Production\",\"notes\":\"This unit covers the identification and classification of crops, essential care practices for growing crops, and methods for harvesting and storing produce.\",\"criteria\":[],\"subtopics\":[{\"title\":\"Types of Crops\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\"],\"detail\":\"at least five crops grown in their community\",\"text\":\"Define at least five crops grown in their community\"},{\"actions\":[\"compare\"],\"detail\":\"crops into food crops and cash crops\",\"text\":\"Compare crops into food crops and cash crops\"},{\"actions\":[\"identify\"],\"detail\":\"crops from pictures or real samples\",\"text\":\"Identify crops from pictures or real samples\"}]},{\"title\":\"Caring for Crops\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"explain\"],\"detail\":\"why weeding is important\",\"text\":\"Explain why weeding is important\"},{\"actions\":[\"apply\"],\"detail\":\"correct watering of a garden bed\",\"text\":\"Apply correct watering of a garden bed\"},{\"actions\":[\"identify\"],\"detail\":\"common pests that damage crops\",\"text\":\"Identify common pests that damage crops\"}]},{\"title\":\"Harvesting and Storage\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"describe\"],\"detail\":\"signs that show a crop is ready to harvest\",\"text\":\"Describe signs that show a crop is ready to harvest\"},{\"actions\":[\"explain\"],\"detail\":\"simple ways of storing harvested crops\",\"text\":\"Explain simple ways of storing harvested crops\"},{\"actions\":[\"define\"],\"detail\":\"why proper storage prevents food loss\",\"text\":\"Define why proper storage prevents food loss\"}]}]},{\"title\":\"Soil and Water\",\"notes\":\"This unit explores different soil types, practices for maintaining soil health, and the importance of water in farming, including sources and conservation methods.\",\"criteria\":[],\"subtopics\":[{\"title\":\"Types and Properties of Soil\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"describe\"],\"detail\":\"the feel and colour of at least two soil types\",\"text\":\"Describe the feel and colour of at least two soil types\"},{\"actions\":[\"identify\"],\"detail\":\"soil samples brought from home\",\"text\":\"Identify soil samples brought from home\"},{\"actions\":[\"explain\"],\"detail\":\"why loam soil is good for most crops\",\"text\":\"Explain why loam soil is good for most crops\"}]},{\"title\":\"Keeping Soil Healthy\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"explain\"],\"detail\":\"what manure does to soil\",\"text\":\"Explain what manure does to soil\"},{\"actions\":[\"describe\"],\"detail\":\"one way to stop soil from washing away\",\"text\":\"Describe one way to stop soil from washing away\"},{\"actions\":[\"define\"],\"detail\":\"why farmers should not plant the same crop every season\",\"text\":\"Define why farmers should not plant the same crop every season\"}]},{\"title\":\"Water for Farming\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\"],\"detail\":\"at least two sources of water for farming\",\"text\":\"Define at least two sources of water for farming\"},{\"actions\":[\"apply\"],\"detail\":\"a safe way of watering plants\",\"text\":\"Apply a safe way of watering plants\"},{\"actions\":[\"define\"],\"detail\":\"Suggest one way of saving water in the garden\",\"text\":\"Define Suggest one way of saving water in the garden\"}]}]},{\"title\":\"Livestock and Animal Care\",\"notes\":\"This unit introduces common domestic animals and their products, along with the basic needs and care practices required for healthy livestock.\",\"criteria\":[],\"subtopics\":[{\"title\":\"Domestic Animals\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\"],\"detail\":\"at least four domestic animals kept at home\",\"text\":\"Define at least four domestic animals kept at home\"},{\"actions\":[\"list\"],\"detail\":\"products obtained from these animals, such as milk, eggs, and meat\",\"text\":\"List products obtained from these animals, such as milk, eggs, and meat\"},{\"actions\":[\"compare\"],\"detail\":\"an animal to the product it provides\",\"text\":\"Compare an animal to the product it provides\"}]},{\"title\":\"Caring for Animals\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\"],\"detail\":\"the basic needs of a farm animal\",\"text\":\"Define the basic needs of a farm animal\"},{\"actions\":[\"describe\"],\"detail\":\"how to keep an animal shelter clean\",\"text\":\"Describe how to keep an animal shelter clean\"},{\"actions\":[\"explain\"],\"detail\":\"why animals need clean water daily\",\"text\":\"Explain why animals need clean water daily\"}]}]},{\"title\":\"Farm Tools and Safety\",\"notes\":\"This unit familiarizes learners with common farm tools and their correct uses, alongside developing essential safety awareness for working in the garden and handling tools.\",\"criteria\":[],\"subtopics\":[{\"title\":\"Common Farm Tools\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\",\"identify\"],\"detail\":\"at least five farm tools\",\"text\":\"Define at least five farm tools\"},{\"actions\":[\"compare\"],\"detail\":\"each tool to the task it is used for\",\"text\":\"Compare each tool to the task it is used for\"},{\"actions\":[\"apply\"],\"detail\":\"the correct way of holding a hoe\",\"text\":\"Apply the correct way of holding a hoe\"}]},{\"title\":\"Safety on the Farm\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"list\"],\"detail\":\"three safety rules to follow when using farm tools\",\"text\":\"List three safety rules to follow when using farm tools\"},{\"actions\":[\"explain\"],\"detail\":\"why they must wash their hands after garden work\",\"text\":\"Explain why they must wash their hands after garden work\"},{\"actions\":[\"apply\"],\"detail\":\"safe carrying of a garden tool\",\"text\":\"Apply safe carrying of a garden tool\"}]}]},{\"title\":\"Agriculture and the Environment\",\"notes\":\"This unit helps learners appreciate the value of trees and forests, and instills good environmental practices that support sustainable agriculture and conservation.\",\"criteria\":[],\"subtopics\":[{\"title\":\"Trees and Forests\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\"],\"detail\":\"Give three reasons why trees are important\",\"text\":\"Define Give three reasons why trees are important\"},{\"actions\":[\"define\"],\"detail\":\"Take part in planting a tree at school\",\"text\":\"Define Take part in planting a tree at school\"},{\"actions\":[\"explain\"],\"detail\":\"one bad effect of cutting down too many trees\",\"text\":\"Explain one bad effect of cutting down too many trees\"}]},{\"title\":\"Caring for the Environment\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\"],\"detail\":\"why bush fires are harmful\",\"text\":\"Define why bush fires are harmful\"},{\"actions\":[\"describe\"],\"detail\":\"one way to keep a water source clean\",\"text\":\"Describe one way to keep a water source clean\"},{\"actions\":[\"identify\"],\"detail\":\"one action they can take to protect their environment\",\"text\":\"Identify one action they can take to protect their environment\"}]}]},{\"title\":\"Food from the Farm\",\"notes\":\"This unit guides learners through the journey of food from the farm to the table, emphasizing healthy eating habits and the connection between agricultural produce and good nutrition.\",\"criteria\":[],\"subtopics\":[{\"title\":\"From Farm to Table\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"describe\"],\"detail\":\"the steps food takes from farm to table\",\"text\":\"Describe the steps food takes from farm to table\"},{\"actions\":[\"explain\"],\"detail\":\"why food should be washed before eating\",\"text\":\"Explain why food should be washed before eating\"},{\"actions\":[\"define\"],\"detail\":\"Suggest one way to avoid wasting food at home\",\"text\":\"Define Suggest one way to avoid wasting food at home\"}]},{\"title\":\"Healthy Eating from the Farm\",\"notes\":\"\",\"criteria\":[{\"actions\":[\"define\"],\"detail\":\"farm foods that are good for their bodies\",\"text\":\"Define farm foods that are good for their bodies\"},{\"actions\":[\"describe\"],\"detail\":\"what a balanced plate of local food looks like\",\"text\":\"Describe what a balanced plate of local food looks like\"},{\"actions\":[\"define\"],\"detail\":\"Suggest three foods to grow in a small kitchen garden\",\"text\":\"Define Suggest three foods to grow in a small kitchen garden\"}]}]}]}', 'approved', 'Built from approved syllabus extraction items.', NULL, '2026-07-02 08:58:06', '2026-07-02 08:58:06', '2026-07-02 08:58:06', '2026-07-02 08:58:06');
