(761, 10, 3, 'topic', NULL, 'Crop Production', 'This unit covers the identification and classification of crops, essential care practices for growing crops, and methods for harvesting and storing produce.', '35', NULL, NULL, NULL, 1.000, 'approved', 137, '2026-07-02 08:58:05', 301, '{\"topic_name\":\"Crop Production\",\"description\":\"This unit covers the identification and classification of crops, essential care practices for growing crops, and methods for harvesting and storing produce.\",\"confidence\":1,\"subtopics\":[{\"subtopic_name\":\"Types of Crops\",\"learning_objectives\":[\"Name at least five crops grown in their community\",\"Sort crops into food crops and cash crops\",\"Identify crops from pictures or real samples\"],\"skills\":[\"list\",\"identify\"],\"suggested_week\":null,\"exam_relevance\":\"medium\",\"keywords\":[\"food crops\",\"cash crops\",\"vegetables\",\"fruits\",\"maize\",\"beans\",\"cassava\",\"sweet potatoes\",\"tobacco\",\"cotton\",\"groundnuts\"],\"prerequisites\":[\"Basic knowledge of common plants\"],\"confidence\":1},{\"subtopic_name\":\"Caring for Crops\",\"learning_objectives\":[\"Explain why weeding is important\",\"Demonstrate correct watering of a garden bed\",\"Identify common pests that damage crops\"],\"skills\":[\"explain\",\"apply\",\"identify\"],\"suggested_week\":null,\"exam_relevance\":\"high\",\"keywords\":[\"weeding\",\"watering\",\"pests\",\"manure\",\"fertiliser\",\"crop care\"],\"prerequisites\":[\"Basic understanding of plant needs\"],\"confidence\":1},{\"subtopic_name\":\"Harvesting and Storage\",\"learning_objectives\":[\"Describe signs that show a crop is ready to harvest\",\"Explain simple ways of storing harvested crops\",\"State why proper storage prevents food loss\"],\"skills\":[\"describe\",\"explain\"],\"suggested_week\":null,\"exam_relevance\":\"medium\",\"keywords\":[\"harvesting\",\"storage methods\",\"food loss\"],\"prerequisites\":[\"Basic understanding of food and its sources\"],\"confidence\":1}]}'