--
-- Structure for view `assessment_topic_summaries`
--
DROP TABLE IF EXISTS `assessment_topic_summaries`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `assessment_topic_summaries`  AS SELECT `at`.`school_id` AS `school_id`, `subj`.`name` AS `subject_name`, `at`.`topic_name` AS `topic_name`, round(avg(`atm`.`marks_obtained` / nullif(`at`.`marks_allocated`,0) * 100),1) AS `average_score`, sum(case when `atm`.`marks_obtained` / nullif(`at`.`marks_allocated`,0) * 100 < 50 then 1 else 0 end) AS `students_needing_support` FROM (((`assessment_topics` `at` join `assessments` `a` on(`a`.`id` = `at`.`assessment_id` and `a`.`school_id` = `at`.`school_id`)) join `subjects` `subj` on(`subj`.`id` = `a`.`subject_id` and `subj`.`school_id` = `a`.`school_id`)) left join `assessment_topic_marks` `atm` on(`atm`.`assessment_topic_id` = `at`.`id` and `atm`.`school_id` = `at`.`school_id`)) GROUP BY `at`.`school_id`, `subj`.`name`, `at`.`topic_name` ;

